// Writes .generated/openapi.json: docs/openapi.json plus an `x-codeSamples`
// entry on every operation — cURL, Python (requests) and Rust (reqwest) — which
// starlight-openapi shows instead of its own generated samples. Its built-in
// generator offers no Python, and builds against `https://example.com` with
// Basic auth; these call a local OMS with a bearer token, as a trader would.
//
// docs/openapi.json stays the clean, committed spec; this file is a build
// artefact (gitignored), regenerated by `prebuild`/`predev`.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { HTTPSnippet } from "httpsnippet";

const BASE_URL = "http://localhost:3001";
const TARGETS = [
  { lang: "shell", label: "cURL", target: "shell", client: "curl" },
  { lang: "python", label: "Python", target: "python", client: "requests" },
  { lang: "rust", label: "Rust", target: "rust", client: "reqwest" },
];

function resolve(spec, schema) {
  let s = schema;
  while (s?.$ref) s = s.$ref.split("/").slice(1).reduce((o, k) => o?.[k], spec);
  return s ?? {};
}

// A value for `schema`: its own example or default first, then the first enum
// value, then one shaped by its type. Every object property is included, as
// starlight-openapi's own samples do; optional ones with nothing better are null.
export function exampleFor(spec, schema, depth = 0) {
  const s = resolve(spec, schema);
  if (s.example !== undefined) return s.example;
  if (s.default !== undefined) return s.default;
  if (s.enum?.length) return s.enum[0];
  const one = s.allOf?.[0] ?? s.oneOf?.[0] ?? s.anyOf?.[0];
  if (one) return exampleFor(spec, one, depth);
  if (depth > 6) return null;
  switch (s.type) {
    case "object": {
      const required = new Set(s.required ?? []);
      const out = {};
      for (const [name, prop] of Object.entries(s.properties ?? {})) {
        const p = resolve(spec, prop);
        const v = exampleFor(spec, prop, depth + 1);
        out[name] = v === undefined || (!required.has(name) && p.nullable && v === "string") ? null : v;
      }
      return out;
    }
    case "array":
      return [exampleFor(spec, s.items ?? {}, depth + 1)];
    case "integer":
    case "number":
      return 0;
    case "boolean":
      return false;
    case "string":
      if (s.format === "uuid") return "00000000-0000-0000-0000-000000000000";
      if (s.format === "date-time") return "2026-01-02T15:04:05Z";
      if (s.format === "date") return "2026-01-02";
      return "string";
    default:
      return undefined;
  }
}

function har(spec, path, method, op) {
  const params = (op.parameters ?? []).map((p) => resolve(spec, p));
  let url = path;
  const queryString = [];
  for (const p of params) {
    const value = p.example ?? exampleFor(spec, p.schema ?? {});
    if (p.in === "path") url = url.replace(`{${p.name}}`, encodeURIComponent(String(value)));
    // Optional query parameters only when the spec gives a real example.
    if (p.in === "query" && (p.required || p.example !== undefined || p.schema?.example !== undefined)) {
      queryString.push({ name: p.name, value: String(value) });
    }
  }
  const qs = queryString.map(({ name, value }) => `${encodeURIComponent(name)}=${encodeURIComponent(value)}`).join("&");
  const headers = [{ name: "Authorization", value: "Bearer <token>" }];
  const request = {
    method: method.toUpperCase(),
    url: `${BASE_URL}${url}${qs ? `?${qs}` : ""}`,
    httpVersion: "HTTP/1.1",
    cookies: [],
    headers,
    queryString,
    headersSize: -1,
    bodySize: -1,
  };
  const json = op.requestBody && resolve(spec, op.requestBody).content?.["application/json"];
  if (json) {
    headers.push({ name: "Content-Type", value: "application/json" });
    request.postData = { mimeType: "application/json", text: JSON.stringify(exampleFor(spec, json.schema ?? {})) };
  }
  return request;
}

// Whether any success response carries a JSON body. Many OMS writes answer
// 204/202 with none, and httpsnippet always parses one — which raises in
// Python and panics in Rust on an empty body.
function returnsJson(spec, op) {
  return Object.entries(op.responses ?? {}).some(
    ([status, r]) => status.startsWith("2") && resolve(spec, r).content?.["application/json"],
  );
}

const PRINT_STATUS = {
  shell: (src) => src,
  python: (src) => src.replace("print(response.json())", "print(response.status_code)"),
  rust: (src) =>
    src.replace(
      /let results = response\.unwrap\(\)\s*\.json::<serde_json::Value>\(\)\s*\.await\s*\.unwrap\(\);\s*dbg!\(results\);/,
      "let status = response.unwrap().status();\n\n    dbg!(status);",
    ),
};

export function codeSamples(spec, path, method, op) {
  const snippet = new HTTPSnippet(har(spec, path, method, op));
  const json = returnsJson(spec, op);
  return TARGETS.map(({ lang, label, target, client }) => {
    const out = snippet.convert(target, client);
    const source = Array.isArray(out) ? out[0] : out;
    return { lang, label, source: json ? source : PRINT_STATUS[lang](source) };
  });
}

export function withCodeSamples(spec) {
  const copy = structuredClone(spec);
  for (const [path, ops] of Object.entries(copy.paths)) {
    for (const [method, op] of Object.entries(ops)) {
      op["x-codeSamples"] = codeSamples(copy, path, method, op);
    }
  }
  return copy;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const spec = JSON.parse(readFileSync(new URL("../../docs/openapi.json", import.meta.url), "utf8"));
  mkdirSync(new URL("../.generated/", import.meta.url), { recursive: true });
  writeFileSync(new URL("../.generated/openapi.json", import.meta.url), JSON.stringify(withCodeSamples(spec), null, 2));
}
